# Gestion basica de paquetes Android.
Import-Module (Join-Path $PSScriptRoot 'AndroidAdb.psm1') -Force
Initialize-AdbLog | Out-Null
try{$device=Select-CurrentAdbDevice -Persist;if(-not(Test-AdbDeviceReady $device $true)){throw 'El dispositivo no esta listo.'}}catch{Write-Host ("ERROR: {0}"-f $_.Exception.Message)-ForegroundColor Red;exit 1}
function Get-Packages { @(Invoke-AdbCommand -Serial $device.Serial -Arguments @('shell','pm','list','packages','-3'))|ForEach-Object{([string]$_)-replace '^package:',''}|Where-Object{$_ -match '^[A-Za-z][A-Za-z0-9_]*(.[A-Za-z][A-Za-z0-9_]*)+$'} }
while($true){Write-Host '';Write-Host 'GESTION DE APLICACIONES' -ForegroundColor Cyan;Write-Host '1. Listar aplicaciones de usuario';Write-Host '2. Desinstalar paquete';Write-Host '0. Volver';switch(Read-Host 'Opcion'){'1'{try{Get-Packages|Sort-Object|Format-Table -AutoSize}catch{Write-Host $_ -ForegroundColor Red};Read-Host 'Enter'|Out-Null};'2'{$package=Read-Host 'Paquete (ej. com.example.app)';if($package -notmatch '^[A-Za-z][A-Za-z0-9_]*(.[A-Za-z][A-Za-z0-9_]*)+$'){Write-Host 'Paquete invalido.' -ForegroundColor Red;continue};if((Read-Host "Escribe DESINSTALAR para confirmar $package") -ceq 'DESINSTALAR'){try{Invoke-AdbCommand -Serial $device.Serial -Arguments @('shell','pm','uninstall',$package)|Out-Host;Write-Host 'Operacion completada.' -ForegroundColor Green}catch{Write-Host $_ -ForegroundColor Red}}};'0'{break};default{Write-Host 'Opcion invalida.' -ForegroundColor Yellow}}}
